using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using UnityEngine;
using QuietDread;
public static class NarrativeChecks {
 class FakeTransport:ILocalNarrativeTransport {public string tags,reply;public int calls;public Task<string> Send(string path,string json,CancellationToken ct){ct.ThrowIfCancellationRequested();calls++;return Task.FromResult(path=="api/tags"?tags:reply);}}
 static string Valid(ChronicleEvent e){return JsonUtility.ToJson(new StoryReply{eventId=e.id,outcome=e.outcome,commanderLost=e.commanderLost,losses=e.Lost(),survivors=e.Survived(),thread="remember_fallen",text="Silence settles around the command post. The weight of the ledger lingers in every pause, and the distant relays offer no easy comfort."});}
 public static void Run(string root){var lines=new List<string>();Action<bool,string> check=(ok,name)=>{if(!ok)throw new Exception("NARRATIVE CHECK: "+name);lines.Add("PASS "+name);};Action<Action,string> rejects=(action,name)=>{bool rejected=false;try{action();}catch{rejected=true;}check(rejected,name);};var d=Content.Load();
  check(LoopbackTransport.ValidEndpoint("http://127.0.0.1:11434")&&LoopbackTransport.ValidEndpoint("http://localhost:11434")&&LoopbackTransport.ValidEndpoint("http://[::1]:11434"),"loopback endpoints accepted");foreach(var address in new[]{"https://example.com","http://192.168.1.2:11434","http://127.0.0.1.evil.test","http://user@localhost:11434","file:///tmp/model","http://localhost:11434/path","http://localhost:11434?x=1"})check(!LoopbackTransport.ValidEndpoint(address),"endpoint rejected: "+address);
  foreach(string mode in new[]{"trail","conquest"})foreach(int winner in new[]{0,1,2}){var c=Campaign.Create(d,mode,"vermin",d.F("vermin").defaults.ToList());c.ObserveChronicle();int initial=c.journal.Count;c.ObserveChronicle();check(c.journal.Count==initial,"idempotent observation "+mode+winner);if(mode=="trail")c.Visit(c.nodes.First(c.Available));else c.Move(1);var b=c.MakeBattle();var killed=b.Living(0).First(u=>!b.P(u).commander);killed.hp=0;var temporary=b.Add("clawrat",0,6,6,true);temporary.hp=0;b.finished=true;b.winner=winner;b.score[0]=winner==0?30:0;b.score[1]=winner==1?30:0;check(c.Settle(b),"settles "+mode+winner);var e=c.journal.Last(x=>x.kind=="battle");check(e.outcome==(winner==0?"victory":winner==1?"defeat":"draw"),"correct outcome "+mode+winner);check(e.Lost().Length==1&&!e.Lost().Contains("battle-"+temporary.id),"temporary losses separated "+mode+winner);check(e.forces.Any(u=>u.id==killed.persistentId&&u.startHP>0&&u.hp==0),"starting roster and losses retained "+mode+winner);check(e.forces.Where(u=>u.team==0&&u.hp>0&&!u.temporary).All(u=>u.xp>=1),"veteran experience recorded "+mode+winner);int count=c.journal.Count;check(!c.Settle(b)&&c.journal.Count==count,"battle event deduplicated "+mode+winner);var loaded=JsonUtility.FromJson<Campaign>(JsonUtility.ToJson(c));loaded.data=d;loaded.EnsureChronicle();check(loaded.chronicleId==c.chronicleId&&loaded.journal.Count==count,"journal save/load "+mode+winner);check(StoryValidation.Parse(Valid(e),e)!=null,"valid structured prose "+mode+winner);rejects(()=>StoryValidation.Parse(Valid(e).Replace(e.id,"wrong-event"),e),"mismatched event rejected "+mode+winner);}
  var campaign=Campaign.Create(d,"trail","vermin",d.F("vermin").defaults.ToList());campaign.Visit(campaign.nodes.First(campaign.Available));var battle=campaign.MakeBattle();battle.units.First(u=>u.persistentId==campaign.commanderId).hp=0;battle.finished=true;battle.winner=0;campaign.Settle(battle);var loss=campaign.journal.First(e=>e.kind=="battle");check(loss.commanderLost&&campaign.status=="lost"&&campaign.journal.Last().kind=="ending","commander death ends trail and is recorded despite field victory");rejects(()=>StoryValidation.Parse(Valid(loss).Replace("\"commanderLost\":true","\"commanderLost\":false"),loss),"commander contradiction rejected");rejects(()=>StoryValidation.Parse("not json",loss),"malformed reply rejected");rejects(()=>StoryValidation.Parse(Valid(loss).Replace("Silence settles","No casualties. Silence settles"),loss),"unsupported survival claim rejected");rejects(()=>StoryValidation.Parse(Valid(loss).Replace("Silence settles","<script>Silence settles"),loss),"markup rejected");rejects(()=>StoryValidation.Parse(Valid(loss).Replace("remember_fallen","invented_conquest"),loss),"unknown plot theme rejected");
  var legacy=JsonUtility.FromJson<Campaign>("{\"mode\":\"trail\",\"faction\":\"vermin\",\"status\":\"active\"}");legacy.data=d;legacy.EnsureChronicle();legacy.ObserveChronicle();check(legacy.journal.Count==1&&legacy.chronicleId.Length>0,"old campaign with missing narrative fields migrates");for(int i=0;i<140;i++)legacy.AppendChronicle(new ChronicleEvent{mode="trail",kind="campaign decision",changes=new[]{"Test event"}});check(legacy.journal.Count==120&&legacy.archivedEntries==21&&legacy.chronicleMemory.Length<2500,"bounded journal and memory");check(legacy.journal.Select(e=>e.id).Distinct().Count()==120,"monotonic event identities after pruning");check(StoryValidation.Prompt(campaign,loss,false).Length<24000,"prompt budget");
  var conquest=Campaign.Create(d,"conquest","compact",d.F("compact").defaults.ToList());conquest.ObserveChronicle();conquest.gold=9999;conquest.selectedProvince=0;check(conquest.RaiseArmy("captain"),"second expedition fixture");conquest.ObserveChronicle();check(conquest.journal.Last().forces.Select(u=>u.army).Distinct().Count()==2,"multiple armies represented");conquest.provinces[1].owner="compact";conquest.ObserveChronicle();check(conquest.journal.Last().changes.Any(x=>x.Contains("owner")),"territorial changes recorded");
  var transport=new FakeTransport{tags="{\"models\":[{\"name\":\"local\",\"size\":2000000,\"capabilities\":[\"completion\"]},{\"name\":\"cloud\",\"size\":2000000,\"remote_host\":\"https://ollama.com\"},{\"name\":\"embed\",\"size\":2000000,\"capabilities\":[\"embedding\"]}]}"};var provider=new OllamaNarrativeProvider(transport);check(provider.Models(CancellationToken.None).GetAwaiter().GetResult().Length==1,"cloud and embedding models excluded");transport.reply=JsonUtility.ToJson(new OllamaReply{done=true,response=Valid(loss)});check(provider.Generate("local","facts","solemn",400,CancellationToken.None).GetAwaiter().GetResult()==Valid(loss),"mocked Ollama success");rejects(()=>provider.Generate("cloud","facts","solemn",400,CancellationToken.None).GetAwaiter().GetResult(),"cloud generation rejected before request");transport.reply="{}";rejects(()=>provider.Generate("local","facts","solemn",400,CancellationToken.None).GetAwaiter().GetResult(),"incomplete provider output rejected");using(var cancel=new CancellationTokenSource()){cancel.Cancel();rejects(()=>provider.Models(cancel.Token).GetAwaiter().GetResult(),"transport cancellation propagated");}
  var saving=Campaign.Create(d,"trail","vermin",d.F("vermin").defaults.ToList());saving.Visit(saving.nodes.First(saving.Available));var activeBattle=saving.MakeBattle();check(saving.BattleForSave(activeBattle)==activeBattle,"active battle retained independent of displayed screen");activeBattle.chronicleCampaignId="another-campaign";check(saving.BattleForSave(activeBattle)==null,"foreign campaign battle not saved");activeBattle.chronicleCampaignId=saving.chronicleId;saving.settled=true;check(saving.BattleForSave(activeBattle)==null,"settled battle not saved");
  loss.location="Ash Reach 2";check(StoryValidation.Parse(Valid(loss).Replace("Silence settles","Silence settles over Ash Reach 2"),loss)!=null,"exact numbered location allowed in prose");rejects(()=>StoryValidation.Parse(Valid(loss).Replace("Silence settles","30 soldiers returned. Silence settles"),loss),"invented numerical assertion rejected");campaign.AppendChronicle(new ChronicleEvent{kind="campaign decision",mode="trail",changes=new[]{"FUTURE_EVENT_SENTINEL"}});check(!StoryValidation.Prompt(campaign,loss,false).Contains("FUTURE_EVENT_SENTINEL"),"future events excluded from historical narration context");
  loss.act=1;rejects(()=>StoryValidation.Parse(Valid(loss).Replace("Silence settles","The trail's end is near. Silence settles"),loss),"premature expedition ending rejected");var unchanged=new ChronicleEvent{id="territory",kind="battle",mode="conquest",outcome="victory",territoryBefore="",territoryAfter=""};rejects(()=>StoryValidation.Parse(Valid(unchanged).Replace("Silence settles","The stronghold is captured. Silence settles"),unchanged),"unsupported territorial claim rejected");
  lines.Insert(0,lines.Count+" narrative event, validation, migration and provider checks passed.");File.WriteAllLines(Path.Combine(root,"Documentation/NARRATIVE-TEST-RESULTS.txt"),lines);
 }
}
